//! `migrate --seed` programme import: the `conveyor-buildout` programme and its projects.
//!
//! The programme is the whole SPEC_V2 buildout. Every current plan is a project in it, and the
//! already-registered GitHub issues are linked from `project.meta.issues`. The document is
//! generated by `scripts/build-programme-seed.py` and committed as `seed/programme.json`.
//!
//! **Idempotent, precisely.** The natural keys are `(tenant, programme.name)` and
//! `(tenant, project.key)`; a second run with an unchanged document creates no row, bumps no
//! version and leaves `updated_at` alone. A changed row is updated and its version bumped.
//!
//! `project.meta` is merged, not replaced: a later PM job may write keys the seed does not own,
//! and a seed run must not erase them. The seed owns the keys it names (`plan`, `track`,
//! `issues`, `depends_on`, `plan_status`, `status_source`) and leaves every other key alone.

use conveyor_domain::TenantId;
use serde::Deserialize;
use serde_json::Value;
use sqlx::{PgConnection, PgPool};
use uuid::Uuid;

use crate::scope::begin_scoped;
use crate::seed::SeedError;
use crate::tenants;

/// The checked-in programme document.
pub const PROGRAMME_EXPORT: &str = include_str!("../../../seed/programme.json");

/// The document's top level.
#[derive(Debug, Deserialize)]
pub struct ProgrammeExport {
    /// The document format; only `1` is accepted.
    pub version: u32,
    /// The one programme.
    pub programme: ProgrammeSeed,
    /// Every project in the programme.
    pub projects: Vec<ProjectSeed>,
}

/// The programme row the seed owns.
#[derive(Debug, Deserialize)]
pub struct ProgrammeSeed {
    /// Unique per tenant.
    pub name: String,
    /// `active | paused | closed`.
    pub status: String,
}

/// One project row the seed owns.
#[derive(Debug, Deserialize)]
pub struct ProjectSeed {
    /// Unique per tenant; `S00`…`S21`, `T0`…`T17`, or a cross-cutting key.
    pub key: String,
    /// Display name.
    pub name: String,
    /// One line naming the plan.
    pub description: String,
    /// `draft | active | paused | closed | archived`.
    pub status: String,
    /// The source repository, when the project has one.
    #[serde(default)]
    pub repo_url: Option<String>,
    /// The project's configuration: `plan`, `track`, `issues`, `depends_on`, …
    pub meta: Value,
}

/// What one seed run did in one tenant.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ProgrammeCounts {
    /// Rows inserted.
    pub created: i64,
    /// Rows whose content changed.
    pub updated: i64,
    /// Rows already at the seeded content.
    pub skipped: i64,
}

/// Parse the embedded document. A malformed document is a build-time error, never a data error.
pub fn programme_export() -> Result<ProgrammeExport, SeedError> {
    let export: ProgrammeExport = serde_json::from_str(PROGRAMME_EXPORT)
        .map_err(|error| SeedError::ProgrammeDocument(error.to_string()))?;
    if export.version != 1 {
        return Err(SeedError::ProgrammeDocument(format!(
            "unsupported version {}",
            export.version
        )));
    }
    Ok(export)
}

/// Apply the programme document to one tenant, or to every active tenant.
///
/// The caller resolves the pool (the migrate connection has DDL rights; tests use the superuser
/// pool). Every write runs in a tenant-scoped transaction, so the row and its tenant agree.
pub async fn seed_programme(
    pool: &PgPool,
    tenant_slug: Option<&str>,
) -> Result<Vec<(String, ProgrammeCounts)>, SeedError> {
    let export = programme_export()?;
    let targets = targets(pool, tenant_slug).await?;
    let mut results = Vec::with_capacity(targets.len());
    for (tenant_id, slug) in targets {
        let tenant = TenantId::from_uuid(tenant_id)?;
        let mut tx = begin_scoped(pool, tenant).await?;
        let mut counts = ProgrammeCounts::default();
        let programme_id =
            upsert_programme(&mut tx, tenant_id, &export.programme, &mut counts).await?;
        for project in &export.projects {
            upsert_project(&mut tx, tenant_id, programme_id, project, &mut counts).await?;
        }
        tx.commit().await?;
        results.push((slug, counts));
    }
    Ok(results)
}

/// The same target resolution `seed_catalogue` uses: one explicit slug, or every active tenant.
pub(crate) async fn targets(
    pool: &PgPool,
    tenant_slug: Option<&str>,
) -> Result<Vec<(Uuid, String)>, SeedError> {
    match tenant_slug {
        Some(slug) => {
            let id: Option<Uuid> = sqlx::query_scalar("SELECT id FROM tenant WHERE slug = $1")
                .bind(slug)
                .fetch_optional(pool)
                .await?;
            let id = id.ok_or_else(|| SeedError::UnknownTenant(slug.to_owned()))?;
            Ok(vec![(id, slug.to_owned())])
        }
        None => {
            let mut out = Vec::new();
            for tenant in tenants::active_ids(pool).await? {
                let slug: Option<String> =
                    sqlx::query_scalar("SELECT slug FROM tenant WHERE id = $1")
                        .bind(tenant.as_uuid())
                        .fetch_optional(pool)
                        .await?;
                let slug = slug.ok_or(SeedError::Missing("tenant", "active tenant re-read"))?;
                out.push((tenant.as_uuid(), slug));
            }
            Ok(out)
        }
    }
}

async fn upsert_programme(
    conn: &mut PgConnection,
    tenant_id: Uuid,
    seed: &ProgrammeSeed,
    counts: &mut ProgrammeCounts,
) -> Result<Uuid, SeedError> {
    let existing: Option<(Uuid, String)> =
        sqlx::query_as("SELECT id, status FROM programme WHERE tenant_id = $1 AND name = $2")
            .bind(tenant_id)
            .bind(&seed.name)
            .fetch_optional(&mut *conn)
            .await?;
    match existing {
        Some((id, status)) if status == seed.status => {
            counts.skipped += 1;
            Ok(id)
        }
        Some((id, _)) => {
            sqlx::query(
                "UPDATE programme
                    SET status = $3, version = version + 1, updated_at = now()
                  WHERE tenant_id = $1 AND id = $2",
            )
            .bind(tenant_id)
            .bind(id)
            .bind(&seed.status)
            .execute(&mut *conn)
            .await?;
            counts.updated += 1;
            Ok(id)
        }
        None => {
            let id: Uuid = sqlx::query_scalar(
                "INSERT INTO programme (tenant_id, name, status)
                 VALUES ($1, $2, $3)
                 RETURNING id",
            )
            .bind(tenant_id)
            .bind(&seed.name)
            .bind(&seed.status)
            .fetch_one(&mut *conn)
            .await?;
            counts.created += 1;
            Ok(id)
        }
    }
}

#[derive(Debug, sqlx::FromRow)]
struct ExistingProject {
    id: Uuid,
    name: String,
    description: String,
    status: String,
    programme_id: Option<Uuid>,
    repo_url: Option<String>,
    meta: Value,
}

async fn upsert_project(
    conn: &mut PgConnection,
    tenant_id: Uuid,
    programme_id: Uuid,
    seed: &ProjectSeed,
    counts: &mut ProgrammeCounts,
) -> Result<(), SeedError> {
    let existing: Option<ExistingProject> = sqlx::query_as(
        "SELECT id, name, description, status, programme_id, repo_url, meta
           FROM project
          WHERE tenant_id = $1 AND key = $2",
    )
    .bind(tenant_id)
    .bind(&seed.key)
    .fetch_optional(&mut *conn)
    .await?;

    match existing {
        Some(row) => {
            let merged = merge_meta(&row.meta, &seed.meta);
            let unchanged = row.name == seed.name
                && row.description == seed.description
                && row.status == seed.status
                && row.programme_id == Some(programme_id)
                && row.repo_url == seed.repo_url
                && row.meta == merged;
            if unchanged {
                counts.skipped += 1;
                return Ok(());
            }
            sqlx::query(
                "UPDATE project
                    SET name = $3, description = $4, status = $5, programme_id = $6,
                        repo_url = $7, meta = $8, version = version + 1, updated_at = now()
                  WHERE tenant_id = $1 AND id = $2",
            )
            .bind(tenant_id)
            .bind(row.id)
            .bind(&seed.name)
            .bind(&seed.description)
            .bind(&seed.status)
            .bind(programme_id)
            .bind(&seed.repo_url)
            .bind(&merged)
            .execute(&mut *conn)
            .await?;
            counts.updated += 1;
        }
        None => {
            sqlx::query(
                "INSERT INTO project
                    (tenant_id, key, name, description, status, programme_id, repo_url, meta)
                 VALUES ($1, $2, $3, $4, $5, $6, $7, $8)",
            )
            .bind(tenant_id)
            .bind(&seed.key)
            .bind(&seed.name)
            .bind(&seed.description)
            .bind(&seed.status)
            .bind(programme_id)
            .bind(&seed.repo_url)
            .bind(&seed.meta)
            .execute(&mut *conn)
            .await?;
            counts.created += 1;
        }
    }
    Ok(())
}

/// The seed owns its named keys; every other key in `existing` survives.
fn merge_meta(existing: &Value, seed: &Value) -> Value {
    let mut merged = existing.as_object().cloned().unwrap_or_default();
    if let Some(map) = seed.as_object() {
        for (key, value) in map {
            merged.insert(key.clone(), value.clone());
        }
    }
    Value::Object(merged)
}
